import React, { useEffect, useState } from "react";
import moment from "moment";
import { filter, isEmpty, omitBy, isNil } from "lodash";
import { useNavigate } from "react-router-dom";
import { updateApplications } from "../../services/application.services";

import { Grid, Spin, message } from "antd";
import { LoadingOutlined } from "@ant-design/icons";
import EditableForm from "../editableForm/editableForm";

import "./applicationForm.scss";

const ApplicationFormInterview = ({
  application = {},
  editable = true,
  size = "default",
}) => {
  const navigate = useNavigate();

  const [applicationFields, setApplicationFields] = useState({
    status: "idle",
    data: null,
  });

  const isLoading = applicationFields.status !== "success";

  useEffect(() => {
    loadApplicationFields();
  }, []);

  const loadApplicationFields = async () => {
    setApplicationFields({ ...applicationFields, status: "loading" });

    let a;
    if (!isEmpty(application)) {
      a = application;
    }

    let fields = [];

    fields.push({
      name: "interviewDate",
      label: "Interview Date",
      value: a?.interviewDate
        ? moment(a.interviewDate).format("DD MMMM YYYY")
        : null,
      editable: true,
      required: false,
      type: "date",
    });
    fields.push({
      name: "interviewTime",
      label: "Interview Time",
      value: a?.interviewTime ? a.interviewTime : null,
      editable: true,
      required: false,
      type: "time",
    });
    fields.push({
      name: "interviewLink",
      label: "Interview Link (Zoom, Google meet etc.)",
      value: a.interviewLink,
      extra: "For online interview only",
      editable: true,
      type: "website",
    });
    fields.push({
      name: "interviewed",
      label: "Interviewed",
      value: a.interviewed,
      editable: true,
      type: "boolean",
      checkedDesc: "Interview completed",
      uncheckedDesc: "Waiting for interview",
    });

    setApplicationFields({
      ...applicationFields,
      status: "success",
      data: fields,
    });
  };

  const handleUpdateApplication = async ({
    interviewDate,
    interviewTime,
    interviewLink,
    interviewed,
  }) => {
    const res = await updateApplications({
      adoptionApplication: omitBy(
        {
          ...application,
          interviewDate,
          interviewTime,
          interviewLink,
          interviewed,

          adopterID: application.adopterID._id,
          petID: application.petID._id,
          rescuerID: application.rescuerID._id,
          paymentID: application.paymentID?._id
            ? application.paymentID._id
            : null,
        },
        (v) => isNil(v) || v.toString().trim() === ""
      ),
    });
    if (res?.error) {
      message.error(res.error.description);
      return false;
    } else {
      message.success("Updated adoption application successfully!");
      return res;
    }
  };

  const breakpoint = Grid.useBreakpoint();

  return (
    <div className="application">
      {isLoading && (
        <>
          <Spin indicator={<LoadingOutlined style={{ fontSize: 24 }} spin />} />
        </>
      )}

      {!isLoading &&
        (editable ? (
          <>
            <EditableForm
              fields={applicationFields.data}
              api={handleUpdateApplication}
              editable={true}
              size={size}
            />
          </>
        ) : (
          <>
            <EditableForm
              fields={filter(applicationFields.data, (v) => {
                return v.name != "image";
              })}
              api={handleUpdateApplication}
              editable={false}
              size={size}
            />
          </>
        ))}
    </div>
  );
};

export default ApplicationFormInterview;
