import React, { useEffect, useState } from "react";
import { omitBy, isNil, map } from "lodash";
import { useNavigate } from "react-router-dom";
import useQuery from "../../hooks/useQuery";
import useAuthContext from "../../hooks/useAuthContext";
import { formatDate, calculateAge } from "../../helpers/date";
import { getPets } from "../../services/pet.services";
import { getAccount } from "../../services/auth.services";
import getColorCodes from "../../helpers/color";

import {
  Row,
  Col,
  Spin,
  Button,
  Tooltip,
  Divider,
  Avatar,
  Tag,
  Modal,
  message,
} from "antd";
import {
  LoadingOutlined,
  MailFilled,
  PhoneFilled,
  FacebookFilled,
  InstagramFilled,
  GlobalOutlined,
  CheckCircleOutlined,
  ExclamationCircleOutlined,
} from "@ant-design/icons";
import { EnvironmentFilled } from "@ant-design/icons";
import LoginModal from "../../components/login-modal/login-modal";

import "./pet.less";
import { useId } from "react";
import { recoverLineBreak } from "../../helpers/text";

const Pet = () => {
  const [petState, setPetState] = useState({ status: "idle", data: null });
  const [visible, setVisible] = useState(false);
  const isLoading = petState.status !== "success";

  useEffect(() => {
    fetchPets();
  }, []);

  const query = useQuery();
  const petID = query.get("petID");

  const fetchPets = async () => {
    setPetState({ ...petState, status: "loading" });

    const params = omitBy(
      { petID },
      (v) => isNil(v) || v.toString().trim() === ""
    );

    const res = await getPets(params);

    if (res?.error) {
      message.error(res.error.description);
    } else {
      const pet = res.petsList[0];
      const colorCodes = getColorCodes(pet.color);
      const age = calculateAge(pet.birthDate);
      const data = { ...pet, colorCodes: colorCodes, age: age };

      setPetState({ ...petState, status: "success", data: data });
    }
  };

  const { accountID, accountType } = useAuthContext();
  const navigate = useNavigate();
  const onClickAdopt = async () => {
    if (!accountID) {
      setVisible(true);
      return;
    }

    if (accountType !== "adopter") {
      message.warning(
        `You are signed in as ${accountType}. Please register/login as an adopter to apply for adoption.`
      );
      return;
    }

    const res = await getAccount({ accountID });
    if (res?.error) {
      message.error(res.error.description);
      return;
    }
    localStorage.setItem("toBeAppliedPet", JSON.stringify(petState.data._id));
    if (!res.account.adoptionFormID) {
      navigate("/adopt/form/new");
    } else {
      navigate("/adopt/application/new");
    }
  };

  const petId = useId();
  useEffect(() => {
    if (petState?.data?.description) {
      document.getElementById(petId).innerHTML = recoverLineBreak(
        petState.data.description
      );
    }
  }, [petState.data]);

  const onCancel = () => {
    setVisible(false);
  };

  const [previewVisible, setPreviewVisible] = useState(false);
  const [previewImage, setPreviewImage] = useState("");
  const handleCancel = () => setPreviewVisible(false);
  const handlePreview = async (image) => {
    setPreviewImage(image);
    setPreviewVisible(true);
  };

  const descForVaccinated =
    "Vaccinations help prevent the pet from catching and spreading some serious infectious diseases, many of which can be fatal. We highly recommend pet owners to discuss with vet a vaccination plan that's right for the pet.";
  const descForSpayedOrNeutered =
    "Spay or neuter the pet can help to manage the population of strays, as well as improve its health. The safest age to spay a cat is between 2 - 5 months old, dogs usually get spayed or neutered before puberty, between 6 - 9 months. We highly recommend pet owners to consult their vets about the plan.";
  const descForDewormed =
    "Deworming the pet contributes to its health. We recommend pet owner to discuss with vet for a deworming plan.";

  const leftColProps = { xxl: 15, xl: 15, lg: 15, md: 15, sm: 24, xs: 24 };
  const rightColProps = { xxl: 9, xl: 9, lg: 9, md: 9, sm: 24, xs: 24 };
  const detailsProps = { xxl: 8, xl: 8, lg: 8, md: 12, sm: 12, xs: 12 };

  return (
    <div className="pet">
      <div className="pet-container">
        <div className="pet-info">
          {isLoading && (
            <>
              <Spin
                indicator={<LoadingOutlined style={{ fontSize: 24 }} spin />}
              />
            </>
          )}

          {!isLoading && (
            <>
              <Row gutter={[16, 16]}>
                <Row gutter={[32, 16]}>
                  <Col {...leftColProps}>
                    <div className="sliders">
                      {map(
                        [petState.data.mainImage, ...petState.data.images],
                        (image, index) => {
                          return (
                            <img
                              alt="pet"
                              src={image}
                              key={index}
                              onClick={() => handlePreview(image)}
                            />
                          );
                        }
                      )}
                    </div>
                  </Col>
                  <Col align="left" {...rightColProps}>
                    <Row className="brief-wrapper outline">
                      <Col span={24}>
                        <h2>{petState.data.name.toUpperCase()}</h2>
                      </Col>

                      <Col span={24} align="left" className="brief">
                        {petState.data.healthCondition === "Healthy" ? (
                          <Tooltip placement="top" title={descForVaccinated}>
                            <Tag icon={<CheckCircleOutlined />} color="green">
                              {petState.data.healthCondition}
                            </Tag>
                          </Tooltip>
                        ) : (
                          <Tooltip placement="top" title={descForVaccinated}>
                            <Tag
                              icon={<ExclamationCircleOutlined />}
                              color="red"
                            >
                              {petState.data.healthCondition}
                            </Tag>
                          </Tooltip>
                        )}

                        <Tooltip placement="top" title={descForVaccinated}>
                          {petState.data.vaccinated ? (
                            <Tag icon={<CheckCircleOutlined />} color="green">
                              Vaccinated
                            </Tag>
                          ) : (
                            <Tag
                              icon={<ExclamationCircleOutlined />}
                              color="red"
                            >
                              Not Vaccinated
                            </Tag>
                          )}
                        </Tooltip>

                        <Tooltip
                          placement="top"
                          title={descForSpayedOrNeutered}
                        >
                          {petState.data.spayedOrNeutered ? (
                            <Tag icon={<CheckCircleOutlined />} color="green">
                              Spayed/Neutered
                            </Tag>
                          ) : (
                            <Tag
                              icon={<ExclamationCircleOutlined />}
                              color="red"
                            >
                              Not Spayed/Neutered
                            </Tag>
                          )}
                        </Tooltip>

                        <Tooltip placement="top" title={descForDewormed}>
                          {petState.data.dewormed ? (
                            <Tag icon={<CheckCircleOutlined />} color="green">
                              Dewormed
                            </Tag>
                          ) : (
                            <Tag
                              icon={<ExclamationCircleOutlined />}
                              color="red"
                            >
                              Not Dewormed
                            </Tag>
                          )}
                        </Tooltip>
                      </Col>

                      <Col span={24} align="left" className="location">
                        <EnvironmentFilled style={{ color: "#abaaaa" }} />{" "}
                        {petState.data.city}, {petState.data.stateOrProvince}
                      </Col>
                    </Row>
                  </Col>
                </Row>

                <Row gutter={[32, 16]}>
                  <Col align="left" {...leftColProps}>
                    <Row gutter={[32, 16]}>
                      <Col span={24} align="left">
                        <h5>Posted on {formatDate(petState.data.createdAt)}</h5>
                      </Col>

                      <Col className="description" span={24} id={petId}>
                        Pet's description
                      </Col>

                      <Col className="fee-explanation" span={24}>
                        <h4 className="star">*</h4>
                        <h4>
                          All organizations in ReHome have been verified,
                          indicating that they are likely to be licenced
                          non-governmental organisations (NGOs) or long-term pet
                          rescue organisations. The adoption fee assists them in
                          covering operating costs, pet care, medical bills, and
                          other expenses so that they can continue to save lives
                          and eventually helping more animals in need. As a
                          result, ReHome advises organizations to charge a small
                          fee.
                        </h4>
                      </Col>

                      <Divider />

                      <Col align="left" span={24}>
                        <Row>
                          <h2>More details</h2>
                        </Row>
                        <Row gutter={[16, 16]}>
                          <Col {...detailsProps}>
                            <div className="details outline">
                              <h3>Gender</h3>
                              <div>{petState.data.gender}</div>
                            </div>
                          </Col>
                          <Col {...detailsProps}>
                            <div className="details outline">
                              <h3>Age</h3>
                              <div>{petState.data.age}</div>
                            </div>
                          </Col>
                          <Col {...detailsProps}>
                            <div className="details outline">
                              <h3>Pet Size</h3>
                              <div>{petState.data.petSize}</div>
                            </div>
                          </Col>
                          <Col {...detailsProps}>
                            <div className="details outline">
                              <h3>Breed</h3>
                              <div>{petState.data.breed}</div>
                            </div>
                          </Col>
                          <Col {...detailsProps}>
                            <div className="details outline">
                              <h3>Color</h3>
                              {petState.data.colorCodes.map((c) => (
                                <span
                                  class="dot outline"
                                  style={{ backgroundColor: c }}
                                ></span>
                              ))}
                            </div>
                          </Col>
                          <Col {...detailsProps}>
                            <div className="details outline">
                              <h3>Food Size</h3>
                              <div>{petState.data.foodSize} per day</div>
                            </div>
                          </Col>
                          <Col {...detailsProps}>
                            <div className="details outline">
                              <h3>Food Fee</h3>
                              <div>{petState.data.foodFee} per month</div>
                            </div>
                          </Col>
                        </Row>
                      </Col>
                    </Row>
                    <Row gutter={[22, 22]} className="tips">
                      <Button
                        disabled
                        onClick={() => navigate("/blog/caretips-dog")}
                      >
                        Get more tips about how to take care of{" "}
                        {petState.data.type}
                      </Button>
                    </Row>
                  </Col>
                  {petState.data.active &&
                  !petState.data.adopted &&
                  petState.data.rescuerID.verified ? (
                    <Col {...rightColProps}>
                      <div className="adoption outline">
                        <h4>Adoption fee</h4>
                        <h2>
                          {petState.data.fee === 0
                            ? "FREE"
                            : `RM${petState.data.fee}`}
                        </h2>
                        <Button
                          type="primary"
                          size="large"
                          style={{ width: "100%" }}
                          onClick={onClickAdopt}
                        >
                          Adopt
                        </Button>
                      </div>
                    </Col>
                  ) : (
                    <Col className="not-available outline" {...rightColProps}>
                      <h3>
                        {petState.data.adopted ? (
                          <>{petState.data.name} is adopted.</>
                        ) : (
                          <>
                            {petState.data.name} is not available for adoption.
                          </>
                        )}
                      </h3>
                      <Button
                        type="primary"
                        size="large"
                        style={{ width: "100%" }}
                        disabled
                      >
                        Adopt
                      </Button>
                    </Col>
                  )}
                </Row>

                <Divider />

                <Row className="rescuer" gutter={[32, 16]}>
                  <Col align="left" span={24}>
                    <h2>Contact person </h2>
                  </Col>
                  <Col
                    align="left"
                    span={{ xxl: 10, xl: 10, lg: 10, md: 10, sm: 24, xs: 24 }}
                  >
                    <Row gutter={[16, 16]}>
                      <Col>
                        <Avatar
                          onClick={() => {
                            window.open(
                              `/rescuer?rescuerID=${petState.data.rescuerID._id}`
                            );
                          }}
                          style={{ cursor: "pointer" }}
                          size={64}
                          src={petState.data.rescuerID.image}
                        />
                      </Col>
                      <Col>
                        <h3
                          onClick={() => {
                            window.open(
                              `/rescuer?rescuerID=${petState.data.rescuerID._id}`
                            );
                          }}
                          style={{ cursor: "pointer" }}
                        >
                          {petState.data.rescuerID.name}
                        </h3>
                        <div style={{ wordWrap: "break-word", width: "400px" }}>
                          <EnvironmentFilled style={{ color: "#abaaaa" }} />{" "}
                          {petState.data.rescuerID.address}
                          {", "}
                          {petState.data.rescuerID.city}
                          {", "} {petState.data.rescuerID.stateOrProvince},
                          {petState.data.rescuerID.country}
                        </div>
                      </Col>
                    </Row>
                  </Col>
                  <Col
                    align="left"
                    className="links"
                    span={{ xxl: 10, xl: 10, lg: 10, md: 10, sm: 24, xs: 24 }}
                  >
                    <div>
                      <Button
                        type="text"
                        icon={<MailFilled style={{ color: "grey" }} />}
                      >
                        {petState.data.rescuerID.email}
                      </Button>
                    </div>
                    <div>
                      <Button
                        type="text"
                        icon={<PhoneFilled style={{ color: "grey" }} />}
                      >
                        {petState.data.rescuerID.phone}
                      </Button>
                    </div>
                  </Col>
                  <Col
                    className="links"
                    align="left"
                    span={{ xxl: 10, xl: 10, lg: 10, md: 10, sm: 24, xs: 24 }}
                  >
                    {petState.data.rescuerID.facebookLink && (
                      <Button
                        style={{ marginRight: "20px" }}
                        icon={<FacebookFilled style={{ color: "grey" }} />}
                        onClick={() => {
                          window.open(petState.data.rescuerID.facebookLink);
                        }}
                      />
                    )}

                    {petState.data.rescuerID.instagramLink && (
                      <Button
                        style={{ marginRight: "20px" }}
                        icon={<InstagramFilled style={{ color: "grey" }} />}
                        onClick={() => {
                          window.open(petState.data.rescuerID.instagramLink);
                        }}
                      />
                    )}

                    {petState.data.rescuerID.organizationWebsiteLink && (
                      <Button
                        style={{ marginRight: "20px" }}
                        icon={<GlobalOutlined style={{ color: "grey" }} />}
                        onClick={() => {
                          window.open(
                            petState.data.rescuerID.organizationWebsiteLink
                          );
                        }}
                      />
                    )}

                    <Button
                      href={`/rescuer?rescuerID=${petState.data.rescuerID._id}`}
                    >
                      More pets from {petState.data.rescuerID.name}
                    </Button>
                  </Col>
                </Row>
              </Row>
            </>
          )}
        </div>
      </div>

      <LoginModal visible={visible} onCancel={onCancel} />

      <Modal visible={previewVisible} footer={null} onCancel={handleCancel}>
        <img style={{ width: "100%" }} src={previewImage} />
      </Modal>
    </div>
  );
};

export default Pet;
